#!/usr/bin/env bash
# Write the AUR headway-bin PKGBUILD and .SRCINFO for a release.
# Usage: aur-package.sh <version> <dir with headway_<version>_linux_*.tar.gz> <out dir>
set -euo pipefail
version="$1"
dist="$2"
out="$3"
root="$(cd "$(dirname "$0")/../.." && pwd)"

sha() { sha256sum "$1" | cut -d' ' -f1; }
release="https://github.com/cnu/headway/releases/download/v$version"
raw="https://raw.githubusercontent.com/cnu/headway/v$version"
sum_amd64=$(sha "$dist/headway_${version}_linux_amd64.tar.gz")
sum_arm64=$(sha "$dist/headway_${version}_linux_arm64.tar.gz")
sum_desktop=$(sha "$root/assets/linux/headway.desktop")
sum_icon=$(sha "$root/assets/icon/headway.svg")
desc="A fast, friendly native Git client with workspaces"

cat > "$out/PKGBUILD" <<EOF
# Maintainer: Srinivasan Rangarajan <srinivasanr at gmail dot com>
# Generated by the Headway release workflow (cnu/headway).
pkgname=headway-bin
pkgver=$version
pkgrel=1
pkgdesc="$desc"
arch=('x86_64' 'aarch64')
url="https://github.com/cnu/headway"
license=('MIT OR Apache-2.0')
depends=('git' 'gcc-libs' 'glibc' 'libxkbcommon' 'hicolor-icon-theme')
provides=('headway')
conflicts=('headway')
source=("headway-\$pkgver.desktop::$raw/assets/linux/headway.desktop"
        "headway-\$pkgver.svg::$raw/assets/icon/headway.svg")
source_x86_64=("headway-\$pkgver-x86_64.tar.gz::$release/headway_\${pkgver}_linux_amd64.tar.gz")
source_aarch64=("headway-\$pkgver-aarch64.tar.gz::$release/headway_\${pkgver}_linux_arm64.tar.gz")
sha256sums=('$sum_desktop'
            '$sum_icon')
sha256sums_x86_64=('$sum_amd64')
sha256sums_aarch64=('$sum_arm64')

package() {
    install -Dm755 headway "\$pkgdir/usr/bin/headway"
    install -Dm644 "headway-\$pkgver.desktop" "\$pkgdir/usr/share/applications/headway.desktop"
    install -Dm644 "headway-\$pkgver.svg" "\$pkgdir/usr/share/icons/hicolor/scalable/apps/headway.svg"
}
EOF

# .SRCINFO is what the AUR reads; it mirrors the PKGBUILD (makepkg --printsrcinfo).
cat > "$out/.SRCINFO" <<EOF
pkgbase = headway-bin
	pkgdesc = $desc
	pkgver = $version
	pkgrel = 1
	url = https://github.com/cnu/headway
	arch = x86_64
	arch = aarch64
	license = MIT OR Apache-2.0
	depends = git
	depends = gcc-libs
	depends = glibc
	depends = libxkbcommon
	depends = hicolor-icon-theme
	provides = headway
	conflicts = headway
	source = headway-$version.desktop::$raw/assets/linux/headway.desktop
	source = headway-$version.svg::$raw/assets/icon/headway.svg
	sha256sums = $sum_desktop
	sha256sums = $sum_icon
	source_x86_64 = headway-$version-x86_64.tar.gz::$release/headway_${version}_linux_amd64.tar.gz
	sha256sums_x86_64 = $sum_amd64
	source_aarch64 = headway-$version-aarch64.tar.gz::$release/headway_${version}_linux_arm64.tar.gz
	sha256sums_aarch64 = $sum_arm64

pkgname = headway-bin
EOF
